var
  x1, x2: Integer;
  y: String;
begin

  if (RandomFloat < 0.7) then x1 := 1 else x1 := 0;

  if (RandomFloat < 0.7) then x2 := 1 else x2 := 0;

  if (x1 = 1) then y := 'Z'
              else  if ( x2 = 0) then y := '1'
                                 else y := '0';
end.

var
  x1, x2: Integer;
  x: Real;
  y: String;
  Label MetEnd;
begin

  x:= RandomFloat;

  if (x < 0.17) then
      begin
        x1 := 0;
        x2 := 0;
        goto MetEnd;
      end;

  if (x < 0.34) then
      begin
        x1 := 0;
        x2 := 1;
        goto MetEnd;
      end;

  if (x < 0.5) then
      begin
        x1 := 1;
        x2 := 0;
        goto MetEnd;
      end;

        x1 := 1;
        x2 := 1;
MetEnd:
  if (x1 * x2 = 0) then y := '1'
                        else y := '0';
end.

