        goto MetEnd;
      end;

  if (x < 0.81) then
      begin
        x1 := 1;
        x2 := 0;
        goto MetEnd;
      end;

        x1 := 1;
        x2 := 1;
MetEnd:
  if (x1 OR x2 = 1) then y := '0'
                        else y := '1';
end.

var
  x1, x2, x3: Integer;
  y: String;
begin
  x1 := (Random(10) + 1);
  if (x1 > 3) then x1 := 1 else x1 := 0;

  x2 := (Random(10) + 1);
  if (x2 > 3) then x2 := 1 else x2 := 0;

  x3 := (Random(10) + 1);
  if (x3 > 3) then x3 := 1 else x3 := 0;

  if (x1 AND x2 AND x3 = 1) then y := '0'
                            else y := '1';
end.

