var
  Uin, Rn: Integer;
  Ust, Ist, Rst: Integer;

  IRb, IRn, Rb: Real;
Label MetBegin;
begin

MetBegin:

  Uin := (Random(16) + 15);
  Ust := (Random(6) + 7);
  Rst := (Random(26) + 5);
  Rn := (Random(1000) + 300)/10*10;
  Ist := (Random(16) + 5);

  IRn:= 1000.0*Ust/Rn ;
  IRb:= IRn + Ist ;
  Rb:= 1000.0*(Uin-Ust)/IRb;
  if (Rb < 150) then goto  MetBegin;
end.

var
  Rb, Rn: Integer;
  Ust, Imin, Imax: Integer;

  IRb, IRn, Uin: Real;
  Label MetBegin;
begin

MetBegin:

  Rb := (Random(501) + 100)/10*10;
