  Ust := (Random(6) + 7);
  Imin := (Random(5) + 1);
  Imax := (Random(25) + 15);

  IRn:= 1000.0*Ust/Rn;
  IRb:= IRn + Imin ;
  Uin:= Ust + Rb*IRb/1000.0

end.

