var
  fl, fh, t: Integer;
  tr: Real;

begin
  fl := (Random(201) + 20)/10*10;
  fh := (Random(150) + 20)/10*10;
  t := (Random(301) + 100)/10*10;

  tr:= 350.0/fh;

end.

var
  fl, fh, t, tin: Integer;
  delta: Real;

begin
 repeat
  fl := (Random(201) + 20)/10*10;
  fh := (Random(150) + 20)/10*10;
  tin:= 10000/fl ;
  t := (Random(100) + tin)/10*10 ;


  delta:= 2.0e-4*pi*fl*t ;

  until  delta < 15.0 ;

end.

