var
  x1, x2: Integer;
  x: Real;
  y: String;
  Label MetEnd;
begin

  x:= RandomFloat;

  if (x < 0.2) then
      begin
        x1 := 0;
        x2 := 0;
        goto MetEnd;
      end;

  if (x < 0.4) then
      begin
        x1 := 0;
        x2 := 1;
        goto MetEnd;
      end;

  if (x < 0.6) then
      begin
        x1 := 1;
        x2 := 0;
        goto MetEnd;
      end;

        x1 := 1;
        x2 := 1;
MetEnd:
  if (x1 * x2 = 0) then y := 'Z'
                        else y := '0';
end.

